10. Create a login API endpoint that checks if the user exists in the database and returns a JWT token if authentication is successful:
```
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const User = require('./models/User');
const secret = 'myappsecret';
const generateToken = (user) => {
  const payload = {
    email: user.email,
  };
  const token = jwt.sign(payload, secret, {
    expiresIn: '1h',
  });
  return token;
};
const handleLogin = (req, res) => {
  const { email, password } = req.body;
  User.findOne({ email }, (err, user) => {
    if (err) {
      res.status(500).json({ error: 'Internal server error' });
      return;
    }
    if (!user) {
      res.status(401).json({ error: 'Invalid email or password' });
      return;
    }
    bcrypt.compare(password, user.password, (err, result) => {
      if (err) {
        res.status(500).json({ error: 'Internal server error' });
        return;
      }
      if (!result) {
        res.status(401).json({ error: 'Invalid email or password' });
        return;
      }
      const token = generateToken(user);
      res.json({ token });
    });
  });
};
module.exports = handleLogin;
```
11. Create a middleware that checks for a valid JWT token on protected API endpoints:
```
const jwt = require('jsonwebtoken');
const secret = 'myappsecret';
const requireAuth = (req, res, next) => {
  const token = req.headers.authorization;
  if (!token) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }
  jwt.verify(token, secret, (err, decoded) => {
    if (err) {
      res.status(401).json({ error: 'Unauthorized' });
      return;
    }
    req.user = decoded;
    next();
  });
};
module.exports = requireAuth;
```
