Algorithm:
1. Read the CSV file and store the planet names and their distances in two separate arrays.
2. Use a sorting algorithm (e.g. bubble sort, insertion sort) to sort the distances array in ascending order.
3. During each iteration of the sorting algorithm, swap the corresponding planet names in the other array to maintain consistency.
4. Return the sorted list of planet names.
Java code implementation:
```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
public class PlanetSorter {
    public static void main(String[] args) {
        String csvFile = "planets.csv";
        String line = "";
        String csvSplitBy = ",";
        String[] planetNames = new String[8];
        double[] planetDistances = new double[8];
        try (BufferedReader br = new BufferedReader(new FileReader(csvFile))) {
            int i = 0;
            while ((line = br.readLine()) != null) {
                String[] planetData = line.split(csvSplitBy);
                planetNames[i] = planetData[0];
                planetDistances[i] = Double.parseDouble(planetData[1].replaceAll(",", ""));
                i++;
            }
            // Bubble sort algorithm
            for (int j = 0; j < planetDistances.length - 1; j++) {
                for (int k = 0; k < planetDistances.length - j - 1; k++) {
                    if (planetDistances[k] > planetDistances[k + 1]) {
                        // Swap distances
                        double tempDistance = planetDistances[k];
                        planetDistances[k] = planetDistances[k + 1];
                        planetDistances[k + 1] = tempDistance;
                        // Swap planet names
                        String tempName = planetNames[k];
                        planetNames[k] = planetNames[k + 1];
                        planetNames[k + 1] = tempName;
                    }
                }
            }
            // Print sorted list of planets
            System.out.println("Sorted list of planets based on distance from the sun:");
            for (String planet : planetNames) {
                System.out.println(planet);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```
