func getUserData(name: String) -> (Int, Int)? {
    let user = users.filter(self.name == name)
    if let userData = try! db.pluck(user) {
        return (userData[steps], userData[goal])
    } else {
        return nil
    }
}
// Update user data in the database
func updateUserData(name: String, steps: Int, goal: Int) {
    let user = users.filter(self.name == name)
    if let userData = try! db.pluck(user) {
        try! db.run(user.update(self.steps <- userData[steps] + steps))
    } else {
        try! db.run(users.insert(self.name <- name, self.steps <- steps, self.goal <- goal))
    }
}
// Calculate progress towards goal
func calculateProgress(name: String) -> Double {
    if let (steps, goal) = getUserData(name: name) {
        return Double(steps) / Double(goal)
    } else {
        return 0
