class Program {
    static void Main(string[] args) {
        string sentence = "Happy deeds are not as great as deeds of yore, but are they not worth a try?";
        // Remove all non-letter characters and convert to lowercase
        string cleanSentence = new string(sentence.ToLower().Where(Char.IsLetter).ToArray());
        // Check if sentence is a palindrome
        bool isPalindrome = cleanSentence.SequenceEqual(cleanSentence.Reverse());
        // Find all anagrams (excluding "deeds")
        var anagrams = cleanSentence.Split(' ')
            .Where(w => w != "deeds")
            .GroupBy(w => new string(w.OrderBy(c => c).ToArray()))
            .Where(g => g.Count() >= 2)
            .SelectMany(g => g);
        // Check if there are at least two anagrams of each other (excluding "deeds")
        bool hasAnagrams = anagrams.GroupBy(w => new string(w.OrderBy(c => c).ToArray()))
            .All(g => g.Count() >= 2);
        // Print the results
        Console.WriteLine("Sentence is a palindrome: " + isPalindrome);
        Console.WriteLine("Sentence has at least two anagrams of each other (excluding 'deeds'): " + hasAnagrams);
    }
}
